package vn.thiendao.optimizer;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.provider.Settings;import android.widget.*;import android.graphics.Color;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root; int gold=0xffffcf66;
 void page(String title){ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(24,48,24,48);root.setBackgroundColor(0xff101014);s.addView(root);setContentView(s);label(title,26);}
 void label(String t,int size){TextView v=new TextView(this);v.setText(t);v.setTextColor(gold);v.setTextSize(size);v.setPadding(8,16,8,16);root.addView(v);}
 void button(String t,Runnable r){Button b=new Button(this);b.setText(t);b.setTextColor(Color.BLACK);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(gold));root.addView(b);b.setOnClickListener(v->r.run());}
 public void onCreate(Bundle b){super.onCreate(b);home();}
 void home(){page("THIÊN ĐẠO • OPTIMIZER");ActivityManager.MemoryInfo m=new ActivityManager.MemoryInfo();((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getMemoryInfo(m);StatFs f=new StatFs(Environment.getDataDirectory().getPath());int battery=((BatteryManager)getSystemService(BATTERY_SERVICE)).getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY);label("RAM khả dụng: "+m.availMem/1048576+" MB\nBộ nhớ trống: "+f.getAvailableBytes()/1073741824+" GB\nPin: "+battery+"%",20);button("Quét ứng dụng đã cài",()->apps(false));button("Xem ứng dụng hệ thống",()->apps(true));button("Cài đặt bộ nhớ",()->open(Settings.ACTION_INTERNAL_STORAGE_SETTINGS));button("Tối ưu pin",()->open(Settings.ACTION_BATTERY_SAVER_SETTINGS));button("Cài đặt nhà phát triển",()->open(Settings.ACTION_APPLICATION_DEVELOPMENT_SETTINGS));label("Bản thử nghiệm: chưa tích hợp ADB. Không tự gỡ ứng dụng.",14);}
 void open(String action){try{startActivity(new Intent(action));}catch(Exception e){Toast.makeText(this,"Thiết bị không hỗ trợ",0).show();}}
 void apps(boolean system){page(system?"Ứng dụng hệ thống":"Ứng dụng người dùng");button("Quay lại",()->home());List<ApplicationInfo> list=getPackageManager().getInstalledApplications(0);list.sort(Comparator.comparing(a->a.loadLabel(getPackageManager()).toString()));for(ApplicationInfo a:list){if(((a.flags&ApplicationInfo.FLAG_SYSTEM)!=0)!=system||a.packageName.equals(getPackageName()))continue;String name=a.loadLabel(getPackageManager()).toString();label(name+"\n"+a.packageName,15);button(system?"Thông tin • không tự gỡ":"Xem / gỡ cài đặt",()->{new AlertDialog.Builder(this).setTitle(name).setMessage(system?"Ứng dụng hệ thống được bảo vệ.":"Chỉ gỡ nếu bạn không cần ứng dụng này.").setNegativeButton("Hủy",null).setPositiveButton("Thông tin",(d,w)->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+a.packageName)))).show();});}}
}